using System;
using System.Collections.Generic;
using System.Linq;
namespace LoopPedal {
sealed partial class Engine {
 public bool Destructive;
 sealed class BankState {public Layer[] Layers;public int Frames,WarpFrames;public long Origin;public bool Warp,Destructive;public long Bytes;}
 readonly List<BankState> undoStates=new List<BankState>(),redoStates=new List<BankState>();
 const long HistoryBytes=256L*1024*1024;
 static Layer CopyLayer(Layer t){return new Layer{Name=t.Name,Original=t.Original,Audio=t.Audio,Stretch=t.Stretch,Pitch=t.Pitch,Gain=t.Gain,Pan=t.Pan,Cutoff=t.Cutoff,TrimStart=t.TrimStart,TrimLength=t.TrimLength,Mute=t.Mute,Solo=t.Solo,Reverse=t.Reverse,PreserveFormants=t.PreserveFormants,LiveMode=t.LiveMode,Offset=t.Offset,LivePlaybackFrames=t.LivePlaybackFrames};}
 BankState CaptureState(){return new BankState{Layers=Layers.Select(CopyLayer).ToArray(),Frames=Layers.Count==0?0:LoopFrames,Origin=Layers.Count==0?Frame:LoopOrigin,Warp=WarpLayers,WarpFrames=WarpFrames,Destructive=Destructive,Bytes=Layers.Sum(t=>(long)t.Original.Length*4+(object.ReferenceEquals(t.Audio,t.Original)?0:(long)t.Audio.Length*4))};}
 static void TrimHistory(List<BankState> states){while(states.Count>1&&(states.Count>12||states.Sum(x=>x.Bytes)>HistoryBytes))states.RemoveAt(0);}
 public int UndoCount{get{lock(Gate)return undoStates.Count;}}public int RedoCount{get{lock(Gate)return redoStates.Count;}}
 public void Checkpoint(){lock(Gate){undoStates.Add(CaptureState());TrimHistory(undoStates);redoStates.Clear();}}
 void RestoreState(BankState state){CancelWarp();foreach(var t in Layers){if(t.RenderCancellation!=null)t.RenderCancellation.Cancel();t.Revision++;}foreach(var t in Layers)if(t.Stream!=null){retiredWarp.Enqueue(t.Stream);t.Stream=null;}Layers=state.Layers.Select(CopyLayer).ToList();LoopFrames=state.Frames;LoopOrigin=state.Origin;WarpFrames=state.WarpFrames;WarpLayers=state.Warp;Destructive=state.Destructive;PlaybackPending=false;}
 public bool Undo(){if(Recording){Finish(false);return true;}lock(Gate){if(undoStates.Count==0)return false;redoStates.Add(CaptureState());TrimHistory(redoStates);var state=undoStates[undoStates.Count-1];undoStates.RemoveAt(undoStates.Count-1);RestoreState(state);return true;}}
 public bool Redo(){lock(Gate){if(Recording)throw new Exception("Finish recording first.");if(redoStates.Count==0)return false;undoStates.Add(CaptureState());TrimHistory(undoStates);var state=redoStates[redoStates.Count-1];redoStates.RemoveAt(redoStates.Count-1);RestoreState(state);return true;}}
 public void ClearLoop(){if(Recording)Finish(false);lock(Gate){if(Layers.Count==0)return;Checkpoint();foreach(var t in Layers){if(t.RenderCancellation!=null)t.RenderCancellation.Cancel();t.Revision++;}foreach(var t in Layers)if(t.Stream!=null){retiredWarp.Enqueue(t.Stream);t.Stream=null;}Layers.Clear();LoopFrames=0;LoopOrigin=Frame;CancelWarp();PlaybackPending=false;}}
 public void DeleteLayer(Layer t){lock(Gate){if(Recording)throw new Exception("Finish recording first.");if(!Layers.Contains(t))return;Checkpoint();Layers.Remove(t);if(t.Stream!=null){retiredWarp.Enqueue(t.Stream);t.Stream=null;}if(Layers.Count==0){LoopFrames=0;CancelWarp();}}}
 float[] BakeLayers(Layer[] layers,int frames,long origin,bool warp){if(layers.Length==1){var t=layers[0];if(!t.Mute&&!t.Reverse&&t.TrimStart==0&&t.TrimLength==1&&t.Stretch==1&&t.Pitch==0&&t.Gain==1&&t.Pan==0&&t.Cutoff>=19999&&t.Audio.Length==frames*2&&(warp||t.Offset==origin))return (float[])t.Audio.Clone();}var result=new float[frames*2];bool solo=layers.Any(t=>t.Solo);foreach(var t in layers){if(t.Mute||solo&&!t.Solo)continue;var source=DSP.Region(t.Original,t.TrimStart,t.TrimLength);double ratio=warp?frames/(double)(source.Length/2):t.Stretch;var audio=DSP.Render(source,ratio,t.Pitch,t.Reverse,default(System.Threading.CancellationToken),t.PreserveFormants);int n=audio.Length/2;double l=0,r=0,alpha=t.Cutoff>=19999?1:1-Math.Exp(-2*Math.PI*t.Cutoff/DSP.Rate);for(int i=-frames;i<frames;i++){int pos=(int)((((warp?i:origin+i-t.Offset))%n+n)%n);l+=alpha*(Edge(audio,pos,0)-l);r+=alpha*(Edge(audio,pos,1)-r);if(i>=0){result[i*2]+=(float)(l*t.Gain*Math.Min(1,1-t.Pan));result[i*2+1]+=(float)(r*t.Gain*Math.Min(1,1+t.Pan));}}}return result;}
 public void SetDestructive(bool enabled){if(Recording)Finish(false);if(enabled==Destructive)return;if(!enabled){Checkpoint();Destructive=false;return;}Layer[] snapshot;int frames;long origin;bool warp;lock(Gate){snapshot=Layers.Select(CopyLayer).ToArray();frames=LoopFrames;origin=LoopOrigin;warp=WarpLayers;}float[] audio=snapshot.Length>0?BakeLayers(snapshot,frames,origin,warp):null;lock(Gate){Checkpoint();CancelWarp();Destructive=true;if(audio!=null){foreach(var t in Layers){if(t.RenderCancellation!=null)t.RenderCancellation.Cancel();t.Revision++;}foreach(var t in Layers)if(t.Stream!=null){retiredWarp.Enqueue(t.Stream);t.Stream=null;}Layers.Clear();Layers.Add(new Layer{Name="Loop",Original=audio,Audio=audio,Offset=origin});LoopFrames=frames;LoopOrigin=origin;}}}
 public void CommitLayer(Layer layer){if(!Destructive){lock(Gate){Checkpoint();Layers.Add(layer);}return;}Layer[] snapshot;int frames;long origin;lock(Gate){snapshot=Layers.Select(CopyLayer).ToArray();frames=LoopFrames>0?LoopFrames:layer.Audio.Length/2;origin=Layers.Count>0?LoopOrigin:layer.Offset;}var audio=snapshot.Length>0?BakeLayers(snapshot,frames,origin,false):new float[frames*2];int n=layer.Audio.Length/2;bool splice=((layer.Offset-origin)%n+n)%n!=0;for(int i=0;i<frames;i++){int pos=(int)(((origin+i-layer.Offset)%n+n)%n);audio[i*2]+=splice?(float)Edge(layer.Audio,pos,0):layer.Audio[pos*2];audio[i*2+1]+=splice?(float)Edge(layer.Audio,pos,1):layer.Audio[pos*2+1];}lock(Gate){Checkpoint();foreach(var t in Layers){if(t.RenderCancellation!=null)t.RenderCancellation.Cancel();t.Revision++;}foreach(var t in Layers)if(t.Stream!=null){retiredWarp.Enqueue(t.Stream);t.Stream=null;}var previous=Layers.Count==1?Layers[0].Audio:null;Layers.Clear();Layers.Add(new Layer{Name="Loop",Original=audio,Audio=audio,Offset=origin,PreviousAudio=previous,Transition=previous==null?0:960,SmoothL=1,SmoothR=1});LoopFrames=frames;LoopOrigin=origin;CancelWarp();}}
}
partial class Pedal {
 bool singleMode;System.Windows.Forms.TableLayoutPanel bankLayout;System.Windows.Forms.Control[] bankPanels=new System.Windows.Forms.Control[2];PadButton layoutPad;
 void SetSingleMode(bool single){singleMode=single;loopers[1].FxMuted=single;if(syncFxBanks!=null)syncFxBanks();if(single){var b=loopers[1];if(b.Recording)b.Finish(false);b.Playing=false;b.PlaybackPending=false;if(loopers[0].StartQuantize==2){loopers[0].StartQuantize=0;var choice=bankPanels[0].Controls.Find("StartQuantize0",true).FirstOrDefault() as StudioChoice;if(choice!=null)choice.SelectedIndex=0;}SelectBank(0);}bankPanels[1].Visible=!single;bankLayout.ColumnStyles[0].Width=single?100:50;bankLayout.ColumnStyles[1].Width=single?0:50;layoutPad.Text=single?"SINGLE":"DUAL";layoutPad.Lit=single;layoutPad.Invalidate();bankLayout.PerformLayout();if(syncMasterLayout!=null)syncMasterLayout();}
 void RestoreHistory(int bank,bool redo){var bus=loopers[bank];if(redo?bus.Redo():bus.Undo()){foreach(var t in bus.Layers.ToArray())if(bus.WarpLayers||bus.Destructive||t.Pitch!=0||t.Stretch!=1)Process(t);RefreshTracks();}}
 async void SetDestructiveUi(int bank){var bus=loopers[bank];SelectBank(bank);if(bus.Recording)bus.Finish(false);status.Text="Preparing loop…";try{await System.Threading.Tasks.Task.Run(()=>bus.SetDestructive(!bus.Destructive));RefreshTracks();status.Text="";}catch(Exception e){status.Text=e.Message;}}
}
}
